import { create } from "zustand";
import type { Risk, RiskStatus } from "@/types";
import { getAllRisks } from "@/mock/inspections";

interface AppState {
  // 侧栏折叠
  sidebarCollapsed: boolean;
  toggleSidebar: () => void;

  // 当前用户
  currentUser: { name: string; role: string; avatar: string };

  // 风险状态更新（模拟）
  risks: Risk[];
  updateRiskStatus: (riskId: string, status: RiskStatus) => void;
  initRisks: () => void;
}

export const useStore = create<AppState>((set) => ({
  sidebarCollapsed: false,
  toggleSidebar: () => set((s) => ({ sidebarCollapsed: !s.sidebarCollapsed })),

  currentUser: {
    name: "张品控",
    role: "品控主管",
    avatar: "张",
  },

  risks: [],
  updateRiskStatus: (riskId, status) =>
    set((state) => ({
      risks: state.risks.map((r) => (r.id === riskId ? { ...r, status } : r)),
    })),
  initRisks: () => set({ risks: getAllRisks() }),
}));
