import { useState, useMemo } from "react";
import { useNavigate } from "react-router-dom";
import { Plus, Eye } from "lucide-react";
import { Card, PageHeader, Button, GradeBadge, SearchInput } from "@/components/ui";
import { inspections, getStoreName } from "@/mock";
import { cn } from "@/lib/utils";

export default function InspectionList() {
  const navigate = useNavigate();
  const [search, setSearch] = useState("");
  const [statusFilter, setStatusFilter] = useState("all");
  const [page, setPage] = useState(1);

  const filtered = useMemo(() => {
    return inspections.filter((insp) => {
      const storeName = getStoreName(insp.storeId);
      const matchSearch = !search || storeName.includes(search) || insp.id.includes(search);
      const matchStatus = statusFilter === "all" || insp.grade === statusFilter;
      return matchSearch && matchStatus;
    });
  }, [search, statusFilter]);

  const pageSize = 10;
  const totalPages = Math.ceil(filtered.length / pageSize);
  const paged = filtered.slice((page - 1) * pageSize, page * pageSize);

  return (
    <div className="animate-fadeIn">
      <PageHeader
        title="巡检管理"
        subtitle="全部巡检记录"
        actions={
          <Button onClick={() => navigate("/inspection/new")}>
            <Plus className="w-4 h-4" /> 新建巡检
          </Button>
        }
      />

      {/* 筛选栏 */}
      <Card className="p-4 mb-4">
        <div className="flex items-center gap-4">
          <div className="w-64">
            <SearchInput value={search} onChange={(v) => { setSearch(v); setPage(1); }} placeholder="搜索门店名称或巡检编号" />
          </div>
          <div className="flex items-center gap-2">
            <span className="text-sm text-slate-400">评级：</span>
            {["all", "优", "良", "中", "差"].map((g) => (
              <button
                key={g}
                onClick={() => { setStatusFilter(g); setPage(1); }}
                className={cn(
                  "px-3 py-1 rounded text-xs transition cursor-pointer",
                  statusFilter === g
                    ? "bg-brand-900 text-white"
                    : "bg-slate-100 text-slate-500 hover:bg-slate-200"
                )}
              >
                {g === "all" ? "全部" : g}
              </button>
            ))}
          </div>
          <div className="ml-auto text-sm text-slate-400">
            共 {filtered.length} 条记录
          </div>
        </div>
      </Card>

      {/* 表格 */}
      <Card className="overflow-hidden">
        <table className="w-full text-sm">
          <thead>
            <tr className="bg-slate-50 text-slate-500 text-xs">
              <th className="text-left px-4 py-3 font-medium">巡检编号</th>
              <th className="text-left px-4 py-3 font-medium">门店</th>
              <th className="text-left px-4 py-3 font-medium">模板</th>
              <th className="text-left px-4 py-3 font-medium">巡检员</th>
              <th className="text-left px-4 py-3 font-medium">时间</th>
              <th className="text-center px-4 py-3 font-medium">得分</th>
              <th className="text-center px-4 py-3 font-medium">评级</th>
              <th className="text-center px-4 py-3 font-medium">风险数</th>
              <th className="text-center px-4 py-3 font-medium">操作</th>
            </tr>
          </thead>
          <tbody className="divide-y divide-slate-100">
            {paged.map((insp) => (
              <tr
                key={insp.id}
                className="hover:bg-slate-50 cursor-pointer transition"
                onClick={() => navigate(`/inspection/${insp.id}`)}
              >
                <td className="px-4 py-3 text-slate-600 font-mono text-xs">{insp.id}</td>
                <td className="px-4 py-3 text-slate-700">{getStoreName(insp.storeId)}</td>
                <td className="px-4 py-3 text-slate-500">{insp.templateName}</td>
                <td className="px-4 py-3 text-slate-500">{insp.inspector}</td>
                <td className="px-4 py-3 text-slate-500 text-xs">{insp.inspectTime.slice(0, 10)}</td>
                <td className="px-4 py-3 text-center">
                  <span className={cn(
                    "font-bold",
                    insp.score >= 90 ? "text-green-600" :
                    insp.score >= 75 ? "text-blue-600" :
                    insp.score >= 60 ? "text-orange-500" : "text-red-500"
                  )}>
                    {insp.score}
                  </span>
                </td>
                <td className="px-4 py-3 text-center">
                  <GradeBadge grade={insp.grade} />
                </td>
                <td className="px-4 py-3 text-center">
                  {insp.riskCount > 0 ? (
                    <span className="text-orange-500 font-medium">{insp.riskCount} 项</span>
                  ) : (
                    <span className="text-green-500">无风险</span>
                  )}
                </td>
                <td className="px-4 py-3 text-center">
                  <button
                    className="text-brand-600 hover:text-brand-700 cursor-pointer"
                    onClick={(e) => {
                      e.stopPropagation();
                      navigate(`/inspection/${insp.id}`);
                    }}
                  >
                    <Eye className="w-4 h-4 mx-auto" />
                  </button>
                </td>
              </tr>
            ))}
          </tbody>
        </table>

        {/* 分页 */}
        {totalPages > 1 && (
          <div className="flex items-center justify-between px-4 py-3 border-t border-slate-100">
            <span className="text-xs text-slate-400">
              第 {page} / {totalPages} 页
            </span>
            <div className="flex gap-1">
              <Button
                variant="secondary"
                size="sm"
                disabled={page === 1}
                onClick={() => setPage(page - 1)}
              >
                上一页
              </Button>
              <Button
                variant="secondary"
                size="sm"
                disabled={page === totalPages}
                onClick={() => setPage(page + 1)}
              >
                下一页
              </Button>
            </div>
          </div>
        )}
      </Card>
    </div>
  );
}
