import { useParams, useNavigate } from "react-router-dom";
import {
  ArrowLeft, MapPin, Phone, User, Calendar, Store as StoreIcon,
  ArrowRight, ClipboardList, AlertCircle, Camera,
} from "lucide-react";
import {
  Card, PageHeader, Button, ScoreRing, GradeBadge, EmptyState,
} from "@/components/ui";
import { getStore, getInspectionsByStore } from "@/mock";
import { cn } from "@/lib/utils";

export default function StoreDetail() {
  const { id } = useParams();
  const navigate = useNavigate();

  const store = getStore(id || "");
  const inspections = getInspectionsByStore(store.id);

  // 统计
  const totalIns = inspections.length;
  const totalRisks = inspections.reduce((s, i) => s + i.riskCount, 0);
  const avgScore = store.avgScore;
  const grade: "优" | "良" | "中" | "差" =
    avgScore >= 90 ? "优" : avgScore >= 75 ? "良" : avgScore >= 60 ? "中" : "差";

  return (
    <div className="animate-fadeIn">
      <PageHeader
        title={store.name}
        subtitle="门店详情"
        actions={
          <Button variant="secondary" size="md" onClick={() => navigate("/store")}>
            <ArrowLeft className="w-4 h-4" />
            返回列表
          </Button>
        }
      />

      {/* 门店信息卡 */}
      <Card className="p-6 mb-5">
        <div className="flex items-start gap-6">
          {/* 评分环 */}
          <div className="flex flex-col items-center justify-center flex-shrink-0 pr-6 border-r border-slate-100">
            <ScoreRing score={avgScore} size={92} />
            <div className="mt-2">
              <GradeBadge grade={grade} />
            </div>
            <p className="text-xs text-slate-400 mt-1.5">综合评级</p>
          </div>

          {/* 基础信息 */}
          <div className="flex-1 grid grid-cols-2 gap-x-6 gap-y-3">
            <div className="flex items-center gap-2">
              <StoreIcon className="w-4 h-4 text-slate-400" />
              <span className="text-xs text-slate-400">门店名称：</span>
              <span className="text-sm text-slate-700 font-medium">{store.name}</span>
            </div>
            <div className="flex items-center gap-2">
              <span className="w-4 h-4 inline-flex items-center justify-center text-slate-400 text-xs font-mono">#</span>
              <span className="text-xs text-slate-400">门店编号：</span>
              <span className="text-sm text-slate-700 font-mono">{store.code}</span>
            </div>
            <div className="flex items-center gap-2">
              <MapPin className="w-4 h-4 text-slate-400" />
              <span className="text-xs text-slate-400">所在区域：</span>
              <span className="text-sm text-slate-700">{store.region}</span>
            </div>
            <div className="flex items-center gap-2">
              <User className="w-4 h-4 text-slate-400" />
              <span className="text-xs text-slate-400">店长：</span>
              <span className="text-sm text-slate-700">{store.manager}</span>
            </div>
            <div className="flex items-center gap-2">
              <Phone className="w-4 h-4 text-slate-400" />
              <span className="text-xs text-slate-400">联系电话：</span>
              <span className="text-sm text-slate-700 font-mono">{store.phone}</span>
            </div>
            <div className="flex items-center gap-2">
              <Calendar className="w-4 h-4 text-slate-400" />
              <span className="text-xs text-slate-400">开业日期：</span>
              <span className="text-sm text-slate-700">{store.openDate}</span>
            </div>
            <div className="col-span-2 flex items-start gap-2 pt-1">
              <MapPin className="w-4 h-4 text-slate-400 mt-0.5" />
              <span className="text-xs text-slate-400 flex-shrink-0 mt-0.5">详细地址：</span>
              <span className="text-sm text-slate-700">{store.address}</span>
            </div>
          </div>
        </div>

        {/* 三个统计指标 */}
        <div className="grid grid-cols-3 gap-4 mt-6 pt-5 border-t border-slate-100">
          <div className="flex items-center gap-3">
            <div className="w-9 h-9 rounded-lg bg-brand-100 flex items-center justify-center">
              <ClipboardList className="w-4 h-4 text-brand-700" />
            </div>
            <div>
              <p className="text-xs text-slate-400">历史巡检</p>
              <p className="text-base font-semibold text-slate-800">{totalIns} 次</p>
            </div>
          </div>
          <div className="flex items-center gap-3">
            <div className="w-9 h-9 rounded-lg bg-orange-100 flex items-center justify-center">
              <AlertCircle className="w-4 h-4 text-orange-600" />
            </div>
            <div>
              <p className="text-xs text-slate-400">累计风险</p>
              <p className="text-base font-semibold text-slate-800">{totalRisks} 项</p>
            </div>
          </div>
          <div className="flex items-center gap-3">
            <div className="w-9 h-9 rounded-lg bg-green-100 flex items-center justify-center">
              <Camera className="w-4 h-4 text-green-600" />
            </div>
            <div>
              <p className="text-xs text-slate-400">累计照片</p>
              <p className="text-base font-semibold text-slate-800">
                {inspections.reduce((s, i) => s + i.photoCount, 0)} 张
              </p>
            </div>
          </div>
        </div>
      </Card>

      {/* 巡检历史 */}
      <div className="mb-4 flex items-center justify-between">
        <div className="flex items-center gap-2">
          <ClipboardList className="w-4 h-4 text-brand-600" />
          <h3 className="text-sm font-semibold text-slate-700">巡检历史记录</h3>
          <span className="text-xs text-slate-400">共 {inspections.length} 次巡检</span>
        </div>
      </div>

      <Card className="overflow-hidden">
        {inspections.length === 0 ? (
          <EmptyState
            icon={<ClipboardList className="w-12 h-12" />}
            text="暂无巡检记录"
          />
        ) : (
          <table className="w-full text-sm">
            <thead>
              <tr className="bg-slate-50 border-b border-slate-100">
                <th className="px-4 py-3 text-left text-xs font-medium text-slate-500">巡检时间</th>
                <th className="px-4 py-3 text-left text-xs font-medium text-slate-500">使用模板</th>
                <th className="px-4 py-3 text-left text-xs font-medium text-slate-500">巡检员</th>
                <th className="px-4 py-3 text-center text-xs font-medium text-slate-500">得分</th>
                <th className="px-4 py-3 text-center text-xs font-medium text-slate-500">评级</th>
                <th className="px-4 py-3 text-center text-xs font-medium text-slate-500">高风险</th>
                <th className="px-4 py-3 text-center text-xs font-medium text-slate-500">中风险</th>
                <th className="px-4 py-3 text-center text-xs font-medium text-slate-500">低风险</th>
                <th className="px-4 py-3 text-center text-xs font-medium text-slate-500">操作</th>
              </tr>
            </thead>
            <tbody>
              {inspections.map((ins) => (
                <tr
                  key={ins.id}
                  className="border-b border-slate-50 hover:bg-brand-50/30 transition cursor-pointer"
                  onClick={() => navigate(`/inspection/${ins.id}`)}
                >
                  <td className="px-4 py-3 text-xs text-slate-600 font-mono">
                    {ins.inspectTime}
                  </td>
                  <td className="px-4 py-3">
                    <span className="inline-flex items-center gap-1 text-xs text-slate-700">
                      <ClipboardList className="w-3 h-3 text-slate-400" />
                      {ins.templateName}
                    </span>
                  </td>
                  <td className="px-4 py-3 text-xs text-slate-600">
                    <span className="inline-flex items-center gap-1">
                      <User className="w-3 h-3 text-slate-400" />
                      {ins.inspector}
                    </span>
                  </td>
                  <td className="px-4 py-3 text-center">
                    <span className={cn(
                      "text-sm font-bold",
                      ins.score >= 90 ? "text-green-600" :
                      ins.score >= 75 ? "text-brand-600" :
                      ins.score >= 60 ? "text-orange-500" :
                      "text-red-600",
                    )}>
                      {ins.score}
                    </span>
                  </td>
                  <td className="px-4 py-3 text-center">
                    <GradeBadge grade={ins.grade} />
                  </td>
                  <td className="px-4 py-3 text-center">
                    {ins.highRiskCount > 0 ? (
                      <span className="text-xs font-semibold text-red-600">{ins.highRiskCount}</span>
                    ) : (
                      <span className="text-xs text-slate-300">—</span>
                    )}
                  </td>
                  <td className="px-4 py-3 text-center">
                    {ins.midRiskCount > 0 ? (
                      <span className="text-xs font-semibold text-orange-500">{ins.midRiskCount}</span>
                    ) : (
                      <span className="text-xs text-slate-300">—</span>
                    )}
                  </td>
                  <td className="px-4 py-3 text-center">
                    {ins.lowRiskCount > 0 ? (
                      <span className="text-xs font-semibold text-yellow-600">{ins.lowRiskCount}</span>
                    ) : (
                      <span className="text-xs text-slate-300">—</span>
                    )}
                  </td>
                  <td className="px-4 py-3 text-center">
                    <Button
                      variant="ghost"
                      size="sm"
                      onClick={(e) => {
                        e.stopPropagation();
                        navigate(`/inspection/${ins.id}`);
                      }}
                    >
                      查看
                      <ArrowRight className="w-3 h-3" />
                    </Button>
                  </td>
                </tr>
              ))}
            </tbody>
          </table>
        )}
      </Card>

      {/* 底部返回 */}
      <div className="flex justify-center mt-6">
        <Button variant="ghost" size="md" onClick={() => navigate("/store")}>
          <ArrowLeft className="w-4 h-4" />
          返回门店列表
        </Button>
      </div>
    </div>
  );
}
