import { useNavigate } from "react-router-dom";
import { ClipboardList, ArrowRight, CheckCircle, FileText, Target } from "lucide-react";
import { Card, PageHeader, Button } from "@/components/ui";
import { templates } from "@/mock";
import { cn } from "@/lib/utils";

// 模板类型对应的 emoji 与色系
const TYPE_EMOJI: Record<string, string> = {
  daily: "🟢",
  standard: "🔵",
  special: "🔴",
};

const TYPE_ACCENT: Record<string, { ring: string; chip: string; icon: string }> = {
  daily: {
    ring: "hover:border-green-300",
    chip: "bg-green-50 text-green-700 border-green-200",
    icon: "bg-green-500",
  },
  standard: {
    ring: "hover:border-brand-300",
    chip: "bg-brand-50 text-brand-700 border-brand-200",
    icon: "bg-brand-600",
  },
  special: {
    ring: "hover:border-red-300",
    chip: "bg-red-50 text-red-700 border-red-200",
    icon: "bg-red-500",
  },
};

export default function TemplateList() {
  const navigate = useNavigate();

  const goDetail = (id: string) => navigate(`/template/${id}`);

  return (
    <div className="animate-fadeIn">
      <PageHeader
        title="巡检模板"
        subtitle="标准化检查模板管理"
        actions={
          <Button variant="secondary" size="md">
            <FileText className="w-4 h-4" />
            导出模板
          </Button>
        }
      />

      {/* 顶部摘要 */}
      <div className="grid grid-cols-3 gap-4 mb-5">
        <Card className="p-4 flex items-center gap-3">
          <div className="w-10 h-10 rounded-lg bg-green-100 flex items-center justify-center">
            <CheckCircle className="w-5 h-5 text-green-600" />
          </div>
          <div>
            <p className="text-xs text-slate-400">日常快检</p>
            <p className="text-base font-semibold text-slate-800">5 项核心指标</p>
          </div>
        </Card>
        <Card className="p-4 flex items-center gap-3">
          <div className="w-10 h-10 rounded-lg bg-brand-100 flex items-center justify-center">
            <ClipboardList className="w-5 h-5 text-brand-700" />
          </div>
          <div>
            <p className="text-xs text-slate-400">标准巡检</p>
            <p className="text-base font-semibold text-slate-800">12 项全维度</p>
          </div>
        </Card>
        <Card className="p-4 flex items-center gap-3">
          <div className="w-10 h-10 rounded-lg bg-red-100 flex items-center justify-center">
            <Target className="w-5 h-5 text-red-600" />
          </div>
          <div>
            <p className="text-xs text-slate-400">专项检查</p>
            <p className="text-base font-semibold text-slate-800">6 项深度核验</p>
          </div>
        </Card>
      </div>

      {/* 模板卡片 */}
      <div className="grid grid-cols-3 gap-4">
        {templates.map((tpl) => {
          const accent = TYPE_ACCENT[tpl.type] ?? TYPE_ACCENT.standard;
          return (
            <Card
              key={tpl.id}
              className={cn(
                "p-5 transition-all cursor-pointer border-t-4 hover:-translate-y-0.5 hover:shadow-md",
                tpl.color === "green" ? "border-t-green-500" :
                tpl.color === "blue" ? "border-t-brand-600" :
                "border-t-red-500",
                accent.ring,
              )}
            >
              <div
                className="flex flex-col h-full"
                onClick={() => goDetail(tpl.id)}
              >
                {/* 头部 */}
                <div className="flex items-start justify-between mb-3">
                  <div className="flex items-center gap-2">
                    <span className="text-2xl">{TYPE_EMOJI[tpl.type]}</span>
                    <div>
                      <h3 className="text-base font-semibold text-slate-800">{tpl.name}</h3>
                      <p className="text-xs text-slate-400 mt-0.5">{tpl.typeName}</p>
                    </div>
                  </div>
                  <span className={cn("inline-flex items-center px-2 py-0.5 rounded text-xs font-medium border", accent.chip)}>
                    {tpl.itemCount} 项
                  </span>
                </div>

                {/* 描述 */}
                <p className="text-sm text-slate-500 leading-relaxed mb-4 flex-1">
                  {tpl.description}
                </p>

                {/* 检查项预览 */}
                <div className="space-y-1.5 mb-4">
                  {tpl.items.slice(0, 3).map((item, i) => (
                    <div key={i} className="flex items-center gap-2 text-xs text-slate-500">
                      <CheckCircle className="w-3.5 h-3.5 text-slate-300 flex-shrink-0" />
                      <span className="truncate">{item.name}</span>
                    </div>
                  ))}
                  {tpl.itemCount > 3 && (
                    <p className="text-xs text-slate-400 pl-5">
                      还有 {tpl.itemCount - 3} 项检查内容...
                    </p>
                  )}
                </div>

                {/* 底部操作 */}
                <div className="flex items-center justify-between pt-3 border-t border-slate-100">
                  <span className="text-xs text-slate-400">
                    共 {tpl.itemCount} 项检查
                  </span>
                  <Button
                    variant="ghost"
                    size="sm"
                    onClick={(e) => {
                      e.stopPropagation();
                      goDetail(tpl.id);
                    }}
                  >
                    查看详情
                    <ArrowRight className="w-3.5 h-3.5" />
                  </Button>
                </div>
              </div>
            </Card>
          );
        })}
      </div>
    </div>
  );
}
