import type { Store } from "@/types";

const regions = [
  { city: "上海", district: ["浦东新区", "徐汇区", "静安区", "黄浦区", "闵行区", "长宁区"] },
  { city: "杭州", district: ["西湖区", "拱墅区", "滨江区", "余杭区", "萧山区"] },
  { city: "苏州", district: ["姑苏区", "工业园区", "高新区", "吴中区"] },
  { city: "南京", district: ["鼓楼区", "玄武区", "秦淮区", "建邺区"] },
  { city: "深圳", district: ["南山区", "福田区", "罗湖区", "宝安区"] },
];

const managerNames = [
  "王芳", "李明", "张伟", "刘洋", "陈静", "杨磊", "赵敏", "周强",
  "吴婷", "徐勇", "孙丽", "马涛", "朱琳", "胡军", "郭燕", "何鑫",
  "高鹏", "林雪", "罗刚", "郑华",
];

function generateStores(): Store[] {
  const stores: Store[] = [];
  let idx = 0;
  for (const region of regions) {
    const count = 10; // 每个城市约10家
    for (let i = 0; i < count; i++) {
      idx++;
      const district = region.district[i % region.district.length];
      const storeNum = String(idx).padStart(3, "0");
      const scoreBase = 60 + Math.floor(Math.random() * 38);
      stores.push({
        id: `store-${storeNum}`,
        name: `茶小鲜（${region.city}${district}店）`,
        code: `CXX-${storeNum}`,
        address: `${region.city}市${district}xx路${100 + idx}号`,
        region: region.city,
        manager: managerNames[idx % managerNames.length],
        phone: `138${String(10000000 + idx * 137).slice(0, 8)}`,
        openDate: `202${2 + (idx % 4)}-${String(1 + (idx % 12)).padStart(2, "0")}-${String(1 + (idx % 28)).padStart(2, "0")}`,
        avgScore: scoreBase,
      });
    }
  }
  return stores;
}

export const stores: Store[] = generateStores();

export function getStore(id: string) {
  return stores.find((s) => s.id === id) || stores[0];
}

export function getStoreName(id: string) {
  const s = stores.find((s) => s.id === id);
  return s ? s.name : "未知门店";
}
