import { cn } from "@/lib/utils";
import type { ReactNode } from "react";
import type { RiskLevel, Grade } from "@/types";
import { RISK_LEVEL_MAP, RISK_STATUS_MAP, GRADE_MAP } from "@/types";

// 卡片
export function Card({ children, className }: { children: ReactNode; className?: string }) {
  return (
    <div className={cn("bg-white rounded-md card-shadow border border-slate-200/70", className)}>
      {children}
    </div>
  );
}

// 页面头部
export function PageHeader({ title, subtitle, actions }: { title: string; subtitle?: string; actions?: ReactNode }) {
  return (
    <div className="flex items-center justify-between mb-5 pb-4 border-b border-slate-200/80">
      <div>
        <h1 className="text-xl font-semibold text-slate-900">{title}</h1>
        {subtitle && <p className="text-sm text-slate-400 mt-0.5">{subtitle}</p>}
      </div>
      {actions && <div className="flex items-center gap-2">{actions}</div>}
    </div>
  );
}

// 风险等级标签
export function RiskLevelBadge({ level }: { level: RiskLevel }) {
  const cfg = RISK_LEVEL_MAP[level];
  return (
    <span className={cn("inline-flex items-center gap-1 px-2 py-0.5 rounded text-xs font-medium", cfg.bg, cfg.color, cfg.border, "border")}>
      <span className={cn("w-1.5 h-1.5 rounded-full", cfg.dot)} />
      {cfg.label}
    </span>
  );
}

// 风险状态标签
export function RiskStatusBadge({ status }: { status: string }) {
  const cfg = RISK_STATUS_MAP[status as keyof typeof RISK_STATUS_MAP] || RISK_STATUS_MAP.pending;
  return (
    <span className={cn("inline-flex items-center px-2 py-0.5 rounded text-xs font-medium", cfg.color)}>
      {cfg.label}
    </span>
  );
}

// 评级标签
export function GradeBadge({ grade }: { grade: Grade }) {
  const cfg = GRADE_MAP[grade];
  return (
    <span className={cn("inline-flex items-center px-2 py-0.5 rounded text-xs font-bold", cfg.bg, cfg.color)}>
      {grade}
    </span>
  );
}

// 得分环
export function ScoreRing({ score, size = 80 }: { score: number; size?: number }) {
  const radius = (size - 10) / 2;
  const circumference = 2 * Math.PI * radius;
  const offset = circumference - (score / 100) * circumference;
  const color = score >= 90 ? "#16a34a" : score >= 75 ? "#2563eb" : score >= 60 ? "#ea580c" : "#dc2626";
  const grade = score >= 90 ? "优" : score >= 75 ? "良" : score >= 60 ? "中" : "差";

  return (
    <div className="relative inline-flex items-center justify-center" style={{ width: size, height: size }}>
      <svg width={size} height={size} className="-rotate-90">
        <circle cx={size / 2} cy={size / 2} r={radius} fill="none" stroke="#e2e8f0" strokeWidth="5" />
        <circle
          cx={size / 2}
          cy={size / 2}
          r={radius}
          fill="none"
          stroke={color}
          strokeWidth="5"
          strokeDasharray={circumference}
          strokeDashoffset={offset}
          strokeLinecap="round"
          style={{ transition: "stroke-dashoffset 0.8s ease" }}
        />
      </svg>
      <div className="absolute flex flex-col items-center">
        <span className="text-xl font-bold" style={{ color }}>{score}</span>
        <span className="text-xs text-slate-400">{grade}</span>
      </div>
    </div>
  );
}

// 按钮组件
export function Button({
  children,
  variant = "primary",
  size = "md",
  className,
  ...props
}: {
  children: ReactNode;
  variant?: "primary" | "secondary" | "ghost" | "danger";
  size?: "sm" | "md" | "lg";
} & React.ButtonHTMLAttributes<HTMLButtonElement>) {
  const variants = {
    primary: "bg-brand-900 text-white hover:bg-brand-800 shadow-sm",
    secondary: "bg-white text-brand-700 border border-brand-200 hover:bg-brand-50",
    ghost: "text-slate-600 hover:bg-slate-100",
    danger: "bg-red-600 text-white hover:bg-red-700",
  };
  const sizes = { sm: "px-3 py-1 text-xs", md: "px-4 py-2 text-sm", lg: "px-5 py-2.5 text-base" };
  return (
    <button
      className={cn(
        "inline-flex items-center gap-1.5 rounded-md font-medium transition-colors cursor-pointer disabled:pointer-events-none disabled:opacity-50",
        variants[variant],
        sizes[size],
        className,
      )}
      {...props}
    >
      {children}
    </button>
  );
}

// 统计卡片
export function StatCard({
  icon, label, value, trend, color,
}: {
  icon: ReactNode;
  label: string;
  value: string | number;
  trend?: string;
  color: string;
}) {
  return (
    <Card className="p-5 hover:-translate-y-0.5 hover:shadow-md transition-all">
      <div className="flex items-start justify-between gap-4">
        <div>
          <p className="text-sm text-slate-500">{label}</p>
          <p className="text-2xl font-bold text-slate-900 mt-2 tracking-tight">{value}</p>
          {trend && <p className="text-xs text-slate-400 mt-1">{trend}</p>}
        </div>
        <div className={cn("w-11 h-11 rounded-md flex items-center justify-center shadow-sm", color)}>
          {icon}
        </div>
      </div>
    </Card>
  );
}

// 空状态
export function EmptyState({ icon, text }: { icon: ReactNode; text: string }) {
  return (
    <div className="flex flex-col items-center justify-center py-16 text-slate-300">
      {icon}
      <p className="text-sm mt-3">{text}</p>
    </div>
  );
}

// 搜索输入框
export function SearchInput({ value, onChange, placeholder }: { value: string; onChange: (v: string) => void; placeholder?: string }) {
  return (
    <input
      type="text"
      value={value}
      onChange={(e) => onChange(e.target.value)}
      placeholder={placeholder || "搜索..."}
      className="w-full px-3 py-2 text-sm border border-slate-200 rounded-md focus:outline-none focus:ring-2 focus:ring-brand-200 focus:border-brand-400 transition"
    />
  );
}
