import type { PhotoCategory } from "@/types";

const CATEGORY_SCENES: Record<PhotoCategory, { label: string; before: string; after: string; accent: string }> = {
  食材标签: {
    label: "MILK 2026-07-05",
    before: "expired ingredient label in a cold cabinet",
    after: "clean labeled ingredients sorted by expiry date",
    accent: "#ef4444",
  },
  冰箱温度: {
    label: "7.2 C",
    before: "cold cabinet temperature above standard",
    after: "cold cabinet temperature within standard",
    accent: "#0ea5e9",
  },
  操作台: {
    label: "WORKTOP",
    before: "messy worktop with mixed containers",
    after: "clean organized worktop",
    accent: "#f97316",
  },
  台账记录: {
    label: "LOG GAP",
    before: "incomplete paper ledger",
    after: "complete inspection ledger",
    accent: "#8b5cf6",
  },
  垃圾桶: {
    label: "OPEN BIN",
    before: "open waste bin area",
    after: "covered waste bin area",
    accent: "#64748b",
  },
  消毒柜: {
    label: "STERILIZER",
    before: "sterilizer cabinet status panel",
    after: "sterilizer cabinet running normally",
    accent: "#14b8a6",
  },
  仓储: {
    label: "STORAGE",
    before: "storage cartons close to wall and floor",
    after: "storage cartons on racks",
    accent: "#ca8a04",
  },
  洗手池: {
    label: "SINK",
    before: "sink without enough soap",
    after: "sink with soap and dryer",
    accent: "#06b6d4",
  },
  健康证: {
    label: "CERT",
    before: "employee health certificate board",
    after: "valid employee certificate board",
    accent: "#22c55e",
  },
};

function svgPhoto(category: PhotoCategory, isAfter = false) {
  const scene = CATEGORY_SCENES[category];
  const statusColor = isAfter ? "#16a34a" : scene.accent;
  const bg = isAfter ? "#ecfdf5" : "#fff7ed";
  const counter = isAfter ? "#e2e8f0" : "#fed7aa";
  const clutter = isAfter ? "0.18" : "0.55";
  const label = isAfter ? "FIXED" : scene.label;
  const svg = `
    <svg xmlns="http://www.w3.org/2000/svg" width="960" height="720" viewBox="0 0 960 720">
      <defs>
        <linearGradient id="wall" x1="0" x2="1" y1="0" y2="1">
          <stop offset="0" stop-color="${bg}"/>
          <stop offset="1" stop-color="#f8fafc"/>
        </linearGradient>
        <filter id="shadow" x="-20%" y="-20%" width="140%" height="140%">
          <feDropShadow dx="0" dy="12" stdDeviation="16" flood-color="#0f172a" flood-opacity=".16"/>
        </filter>
      </defs>
      <rect width="960" height="720" fill="url(#wall)"/>
      <rect x="72" y="94" width="816" height="62" rx="10" fill="#e2e8f0"/>
      <rect x="72" y="164" width="816" height="392" rx="18" fill="#f8fafc" stroke="#cbd5e1" stroke-width="3" filter="url(#shadow)"/>
      <rect x="112" y="205" width="736" height="110" rx="12" fill="#e0f2fe"/>
      <rect x="112" y="340" width="736" height="138" rx="12" fill="${counter}"/>
      <rect x="136" y="225" width="122" height="68" rx="8" fill="#ffffff" stroke="#94a3b8" stroke-width="2"/>
      <rect x="282" y="225" width="122" height="68" rx="8" fill="#ffffff" stroke="#94a3b8" stroke-width="2"/>
      <rect x="428" y="225" width="122" height="68" rx="8" fill="#ffffff" stroke="#94a3b8" stroke-width="2"/>
      <rect x="604" y="219" width="186" height="82" rx="10" fill="#0f172a"/>
      <text x="697" y="268" text-anchor="middle" font-family="Arial, sans-serif" font-size="34" font-weight="700" fill="${statusColor}">${label}</text>
      <circle cx="188" cy="408" r="34" fill="${statusColor}" opacity="${clutter}"/>
      <rect x="256" y="372" width="122" height="72" rx="12" fill="#94a3b8" opacity="${clutter}"/>
      <rect x="414" y="382" width="180" height="54" rx="10" fill="#64748b" opacity="${isAfter ? ".2" : ".5"}"/>
      <rect x="626" y="360" width="148" height="96" rx="14" fill="${isAfter ? "#bbf7d0" : "#fecaca"}"/>
      <path d="M124 528 H836" stroke="#cbd5e1" stroke-width="8" stroke-linecap="round"/>
      <text x="120" y="622" font-family="Arial, sans-serif" font-size="32" font-weight="700" fill="#1e293b">${category}</text>
      <text x="120" y="660" font-family="Arial, sans-serif" font-size="20" fill="#64748b">${isAfter ? scene.after : scene.before}</text>
      <rect x="684" y="604" width="150" height="42" rx="21" fill="${statusColor}" opacity=".95"/>
      <text x="759" y="632" text-anchor="middle" font-family="Arial, sans-serif" font-size="18" font-weight="700" fill="#ffffff">${isAfter ? "VERIFIED" : "EVIDENCE"}</text>
    </svg>`;
  return `data:image/svg+xml;charset=utf-8,${encodeURIComponent(svg)}`;
}

// 各类别照片的 URL
export const PHOTO_URLS: Record<PhotoCategory, { before: string; after: string }> = {
  食材标签: {
    before: svgPhoto("食材标签"),
    after: svgPhoto("食材标签", true),
  },
  冰箱温度: {
    before: svgPhoto("冰箱温度"),
    after: svgPhoto("冰箱温度", true),
  },
  操作台: {
    before: svgPhoto("操作台"),
    after: svgPhoto("操作台", true),
  },
  台账记录: {
    before: svgPhoto("台账记录"),
    after: svgPhoto("台账记录", true),
  },
  垃圾桶: {
    before: svgPhoto("垃圾桶"),
    after: svgPhoto("垃圾桶", true),
  },
  消毒柜: {
    before: svgPhoto("消毒柜"),
    after: svgPhoto("消毒柜", true),
  },
  仓储: {
    before: svgPhoto("仓储"),
    after: svgPhoto("仓储", true),
  },
  洗手池: {
    before: svgPhoto("洗手池"),
    after: svgPhoto("洗手池", true),
  },
  健康证: {
    before: svgPhoto("健康证"),
    after: svgPhoto("健康证", true),
  },
};

// 获取某类照片 URL
export function getPhotoUrl(category: PhotoCategory, isAfter = false) {
  return PHOTO_URLS[category]?.[isAfter ? "after" : "before"] || PHOTO_URLS.操作台.before;
}
