import type { Inspection, Risk } from "@/types";

type PdfLine = { text: string; size?: number; gap?: number };

function ascii(input: string) {
  return input.replace(/[^\x20-\x7e]/g, "?");
}

function escapePdf(input: string) {
  return ascii(input).replace(/\\/g, "\\\\").replace(/\(/g, "\\(").replace(/\)/g, "\\)");
}

function buildPdf(lines: PdfLine[]) {
  let y = 790;
  const content = lines.map((line) => {
    const size = line.size || 11;
    const text = escapePdf(line.text);
    const command = `BT /F1 ${size} Tf 54 ${y} Td (${text}) Tj ET`;
    y -= line.gap || size + 10;
    return command;
  }).join("\n");

  const objects = [
    "1 0 obj\n<< /Type /Catalog /Pages 2 0 R >>\nendobj\n",
    "2 0 obj\n<< /Type /Pages /Kids [3 0 R] /Count 1 >>\nendobj\n",
    "3 0 obj\n<< /Type /Page /Parent 2 0 R /MediaBox [0 0 595 842] /Resources << /Font << /F1 4 0 R >> >> /Contents 5 0 R >>\nendobj\n",
    "4 0 obj\n<< /Type /Font /Subtype /Type1 /BaseFont /Helvetica >>\nendobj\n",
    `5 0 obj\n<< /Length ${content.length} >>\nstream\n${content}\nendstream\nendobj\n`,
  ];

  let pdf = "%PDF-1.4\n";
  const offsets = [0];
  objects.forEach((obj) => {
    offsets.push(pdf.length);
    pdf += obj;
  });
  const xrefStart = pdf.length;
  pdf += `xref\n0 ${objects.length + 1}\n0000000000 65535 f \n`;
  offsets.slice(1).forEach((offset) => {
    pdf += `${String(offset).padStart(10, "0")} 00000 n \n`;
  });
  pdf += `trailer\n<< /Size ${objects.length + 1} /Root 1 0 R >>\nstartxref\n${xrefStart}\n%%EOF`;
  return pdf;
}

export function downloadInspectionReport(
  inspection: Inspection,
  storeName: string,
  risks: Risk[],
) {
  const lines: PdfLine[] = [
    { text: "Kitchen Sentry Inspection Report", size: 20, gap: 28 },
    { text: `Inspection ID: ${inspection.id}` },
    { text: `Store: ${storeName}` },
    { text: `Template: ${inspection.templateName}` },
    { text: `Inspector: ${inspection.inspector}` },
    { text: `Inspection Time: ${inspection.inspectTime}` },
    { text: `Score: ${inspection.score} / 100` },
    { text: `Risks: High ${inspection.highRiskCount}, Medium ${inspection.midRiskCount}, Low ${inspection.lowRiskCount}`, gap: 24 },
    { text: "Nonconformity Details", size: 15, gap: 22 },
    ...risks.slice(0, 8).map((risk, index) => ({
      text: `${index + 1}. [${risk.level.toUpperCase()}] ${risk.description}`,
      size: 10,
      gap: 16,
    })),
    { text: "", gap: 18 },
    { text: "Rectification Requirement", size: 15, gap: 22 },
    { text: "All confirmed risks should be corrected before the deadline and verified by quality control staff." },
    { text: "AI recognition results are for reference and require manual confirmation." },
  ];

  const blob = new Blob([buildPdf(lines)], { type: "application/pdf" });
  const url = URL.createObjectURL(blob);
  const link = document.createElement("a");
  link.href = url;
  link.download = `${inspection.id}-inspection-report.pdf`;
  document.body.appendChild(link);
  link.click();
  link.remove();
  URL.revokeObjectURL(url);
}
