import { useState, useEffect, useRef } from "react";
import { useNavigate } from "react-router-dom";
import {
  Store as StoreIcon, Camera, Sparkles, Check,
  ScanText, FileSearch, Image, GitCompare, ShieldAlert, ArrowRight,
  Loader2, ChevronRight, AlertCircle, CheckCircle2,
} from "lucide-react";
import { Card, PageHeader, Button } from "@/components/ui";
import { stores, templates, getStoreName } from "@/mock";
import { cn } from "@/lib/utils";

type Phase = "form" | "analyzing" | "done";
const AI_STEPS = [
  { name: "OCR 文字识别", desc: "识别标签、台账上的文字信息", icon: ScanText },
  { name: "信息提取", desc: "提取生产日期、保质期等结构化字段", icon: FileSearch },
  { name: "场景分类", desc: "判断每张照片所属区域（冰箱/操作台/台账...）", icon: Image },
  { name: "标准比对", desc: "对照巡检模板标准逐项检查", icon: GitCompare },
  { name: "风险判定", desc: "生成风险清单，标注等级和置信度", icon: ShieldAlert },
];

export default function InspectionNew() {
  const navigate = useNavigate();
  const [phase, setPhase] = useState<Phase>("form");
  const [storeId, setStoreId] = useState("store-001");
  const [templateId, setTemplateId] = useState("tpl-002");
  const [step, setStep] = useState(-1);
  const [photos, setPhotos] = useState<Record<string, number>>({});
  const timersRef = useRef<ReturnType<typeof setTimeout>[]>([]);

  const template = templates.find((t) => t.id === templateId) || templates[0];
  const uploadedCount = Object.values(photos).reduce((sum, count) => sum + count, 0);

  // AI 分析动画
  useEffect(() => {
    if (phase !== "analyzing") return;
    setStep(-1);
    const timers: ReturnType<typeof setTimeout>[] = [];
    // 短暂延迟后开始第一步
    timers.push(setTimeout(() => setStep(0), 300));
    for (let i = 0; i < 5; i++) {
      timers.push(setTimeout(() => setStep(i), 300 + (i + 1) * 700));
    }
    // 全部完成后切换到 done
    timers.push(setTimeout(() => setPhase("done"), 300 + 6 * 700));
    timersRef.current = timers;
    return () => timers.forEach((t) => clearTimeout(t));
  }, [phase]);

  const handleStart = () => {
    sessionStorage.setItem("demoInspectionDraft", JSON.stringify({ storeId, templateId }));
    setPhase("analyzing");
  };

  const handleViewResult = () => {
    navigate("/inspection/INS-20260708-001");
  };

  const addPhoto = (category: string) => {
    setPhotos((prev) => ({ ...prev, [category]: Math.min((prev[category] || 0) + 1, 3) }));
  };

  // ========== AI 分析动画 ==========
  if (phase === "analyzing" || phase === "done") {
    return (
      <div className="animate-fadeIn max-w-3xl mx-auto py-8">
        <Card className="p-8">
          <div className="text-center mb-8">
            <div className="inline-flex w-16 h-16 rounded-2xl bg-brand-50 items-center justify-center mb-4">
              {phase === "done" ? (
                <CheckCircle2 className="w-8 h-8 text-green-500" />
              ) : (
                <Loader2 className="w-8 h-8 text-brand-600 animate-spin" />
              )}
            </div>
            <h2 className="text-xl font-bold text-slate-800">
              {phase === "done" ? "AI 分析完成" : "AI 正在分析"}
            </h2>
            <p className="text-sm text-slate-400 mt-1">
              {phase === "done"
                ? `已识别 ${5} 项风险，巡检得分 62 分`
                : `正在分析 ${getStoreName(storeId)} 的 ${template.name} 取证照片...`}
            </p>
          </div>

          {/* 步骤动画 */}
          <div className="space-y-4 mb-8">
            {AI_STEPS.map((s, i) => {
              const Icon = s.icon;
              const isDone = phase === "done" || i < step;
              const isActive = phase === "analyzing" && i === step;
              return (
                <div
                  key={i}
                  className={cn(
                    "flex items-center gap-4 p-3 rounded-lg transition-all duration-300",
                    isDone ? "bg-green-50" : isActive ? "bg-brand-50" : "bg-slate-50 opacity-50"
                  )}
                >
                  <div className={cn(
                    "w-10 h-10 rounded-full flex items-center justify-center flex-shrink-0 transition",
                    isDone ? "bg-green-500" : isActive ? "bg-brand-600" : "bg-slate-200"
                  )}>
                    {isDone ? (
                      <Check className="w-5 h-5 text-white" />
                    ) : isActive ? (
                      <Loader2 className="w-5 h-5 text-white animate-spin" />
                    ) : (
                      <Icon className="w-5 h-5 text-slate-400" />
                    )}
                  </div>
                  <div className="flex-1">
                    <p className={cn(
                      "text-sm font-medium transition",
                      isDone ? "text-green-700" : isActive ? "text-brand-700" : "text-slate-400"
                    )}>
                      第{i + 1}步：{s.name}
                    </p>
                    <p className="text-xs text-slate-400">{s.desc}</p>
                  </div>
                  {isDone && (
                    <span className="text-xs text-green-500 font-medium">已完成</span>
                  )}
                  {isActive && (
                    <span className="text-xs text-brand-500 font-medium">分析中...</span>
                  )}
                </div>
              );
            })}
          </div>

          {/* 进度条 */}
          <div className="w-full h-2 bg-slate-100 rounded-full overflow-hidden mb-6">
            <div
              className="h-full bg-gradient-to-r from-brand-600 to-brand-400 rounded-full transition-all duration-500"
              style={{ width: phase === "done" ? "100%" : `${((step + 1) / 5) * 100}%` }}
            />
          </div>

          {/* 完成结果 */}
          {phase === "done" && (
            <div className="animate-fadeIn">
              <div className="bg-slate-50 rounded-lg p-5 mb-6">
                <h3 className="text-sm font-semibold text-slate-700 mb-4 flex items-center gap-2">
                  <Sparkles className="w-4 h-4 text-brand-500" /> AI 识别结果摘要
                </h3>
                <div className="grid grid-cols-4 gap-3">
                  <div className="bg-white rounded-lg p-3 text-center">
                    <p className="text-2xl font-bold text-red-500">3</p>
                    <p className="text-xs text-slate-400 mt-1">高风险</p>
                  </div>
                  <div className="bg-white rounded-lg p-3 text-center">
                    <p className="text-2xl font-bold text-orange-500">2</p>
                    <p className="text-xs text-slate-400 mt-1">中风险</p>
                  </div>
                  <div className="bg-white rounded-lg p-3 text-center">
                    <p className="text-2xl font-bold text-yellow-500">0</p>
                    <p className="text-xs text-slate-400 mt-1">低风险</p>
                  </div>
                  <div className="bg-white rounded-lg p-3 text-center">
                    <p className="text-2xl font-bold text-brand-600">6</p>
                    <p className="text-xs text-slate-400 mt-1">照片已分析</p>
                  </div>
                </div>
                <div className="mt-3 flex items-start gap-2 text-xs text-amber-600 bg-amber-50 rounded-md p-2.5">
                  <AlertCircle className="w-4 h-4 flex-shrink-0 mt-0.5" />
                  <span>AI 识别结果仅供参考，请人工复核确认后生成正式报告。</span>
                </div>
              </div>
              <Button size="lg" className="w-full justify-center" onClick={handleViewResult}>
                查看巡检详情 <ArrowRight className="w-4 h-4" />
              </Button>
            </div>
          )}
        </Card>
      </div>
    );
  }

  // ========== 表单 ==========
  return (
    <div className="animate-fadeIn max-w-4xl mx-auto">
      <PageHeader title="新建巡检" subtitle="选择门店和模板，巡检取证后 AI 自动分析" />

      {/* 步骤1：选择门店 */}
      <Card className="p-5 mb-4">
        <div className="flex items-center gap-2 mb-4">
          <div className="w-6 h-6 rounded-full bg-brand-900 text-white flex items-center justify-center text-xs font-bold">1</div>
          <h3 className="text-sm font-semibold text-slate-700">选择门店</h3>
        </div>
        <div className="grid grid-cols-3 gap-2">
          {stores.slice(0, 12).map((s) => (
            <button
              key={s.id}
              onClick={() => setStoreId(s.id)}
              className={cn(
                "flex items-center gap-2 p-3 rounded-lg border text-left transition cursor-pointer",
                storeId === s.id
                  ? "border-brand-500 bg-brand-50 ring-2 ring-brand-100"
                  : "border-slate-200 hover:border-brand-300 hover:bg-slate-50"
              )}
            >
              <StoreIcon className={cn("w-4 h-4 flex-shrink-0", storeId === s.id ? "text-brand-600" : "text-slate-400")} />
              <div className="flex-1 min-w-0">
                <p className={cn("text-sm truncate", storeId === s.id ? "text-brand-700 font-medium" : "text-slate-600")}>
                  {s.name}
                </p>
                <p className="text-xs text-slate-400">{s.code} · {s.region}</p>
              </div>
              {storeId === s.id && <Check className="w-4 h-4 text-brand-600 flex-shrink-0" />}
            </button>
          ))}
        </div>
        <p className="text-xs text-slate-400 mt-2">已选择：{getStoreName(storeId)}</p>
      </Card>

      {/* 步骤2：选择模板 */}
      <Card className="p-5 mb-4">
        <div className="flex items-center gap-2 mb-4">
          <div className="w-6 h-6 rounded-full bg-brand-900 text-white flex items-center justify-center text-xs font-bold">2</div>
          <h3 className="text-sm font-semibold text-slate-700">选择巡检模板</h3>
        </div>
        <div className="grid grid-cols-3 gap-3">
          {templates.map((t) => (
            <button
              key={t.id}
              onClick={() => { setTemplateId(t.id); setPhotos({}); }}
              className={cn(
                "p-4 rounded-lg border text-left transition cursor-pointer",
                templateId === t.id
                  ? "border-brand-500 bg-brand-50 ring-2 ring-brand-100"
                  : "border-slate-200 hover:border-brand-300 hover:bg-slate-50"
              )}
            >
              <div className="flex items-center justify-between mb-2">
                <span className="text-base">
                  {t.type === "daily" ? "🟢" : t.type === "standard" ? "🔵" : "🔴"}
                </span>
                {templateId === t.id && <Check className="w-4 h-4 text-brand-600" />}
              </div>
              <p className={cn("text-sm font-medium", templateId === t.id ? "text-brand-700" : "text-slate-700")}>
                {t.name}
              </p>
              <p className="text-xs text-slate-400 mt-1">{t.typeName}</p>
              <p className="text-xs text-slate-400 mt-1">{t.itemCount} 项检查</p>
            </button>
          ))}
        </div>
      </Card>

      {/* 步骤3：巡检取证 */}
      <Card className="p-5 mb-4">
        <div className="flex items-center gap-2 mb-4">
          <div className="w-6 h-6 rounded-full bg-brand-900 text-white flex items-center justify-center text-xs font-bold">3</div>
          <h3 className="text-sm font-semibold text-slate-700">巡检取证</h3>
          <span className="text-xs text-slate-400">按模板要求完成取证，AI 将自动分析</span>
          <span className="ml-auto text-xs text-brand-700 bg-brand-50 px-2 py-0.5 rounded">
            已取证 {uploadedCount} 张
          </span>
        </div>
        <div className="space-y-3">
          {template.items.slice(0, 6).map((item, i) => {
            const count = photos[item.category] || 0;
            return (
              <div key={i} className="flex items-center gap-4 p-3 bg-slate-50 rounded-lg">
                <div className="flex-1">
                  <p className="text-sm text-slate-700 font-medium">{item.name}</p>
                  <p className="text-xs text-slate-400 mt-0.5">{item.photoReq}</p>
                </div>
                <div className="flex items-center gap-2">
                  {count > 0 ? (
                    <div className="flex gap-1.5">
                      {Array.from({ length: count }).map((_, idx) => (
                        <div key={idx} className="w-12 h-12 rounded-md bg-gradient-to-br from-brand-100 to-brand-200 flex items-center justify-center">
                          <Camera className="w-4 h-4 text-brand-500" />
                        </div>
                      ))}
                    </div>
                  ) : null}
                  <Button
                    variant="secondary"
                    size="sm"
                    onClick={() => addPhoto(item.category)}
                    disabled={count >= 3}
                  >
                    <Camera className="w-3.5 h-3.5" />
                    {count >= 3 ? "已满" : count > 0 ? `再拍1张` : "巡检取证"}
                  </Button>
                </div>
              </div>
            );
          })}
        </div>
      </Card>

      {/* 提交按钮 */}
      <div className="flex items-center justify-between">
        <Button variant="ghost" onClick={() => navigate("/inspection")}>
          取消
        </Button>
        <Button size="lg" onClick={handleStart} disabled={uploadedCount === 0}>
          <Sparkles className="w-4 h-4" /> 开始 AI 分析
          <ChevronRight className="w-4 h-4" />
        </Button>
      </div>
    </div>
  );
}
