// 门店
export interface Store {
  id: string;
  name: string;
  code: string;
  address: string;
  region: string;
  manager: string;
  phone: string;
  openDate: string;
  avgScore: number;
}

// 巡检照片
export interface Photo {
  id: string;
  inspectionId: string;
  category: PhotoCategory;
  url: string;
  aiResult: string;
  confidence: number;
  // 红框标注位置（百分比）
  box?: { x: number; y: number; w: number; h: number };
}

export type PhotoCategory =
  | "食材标签"
  | "冰箱温度"
  | "操作台"
  | "台账记录"
  | "垃圾桶"
  | "消毒柜"
  | "仓储"
  | "洗手池"
  | "健康证";

// 巡检模板检查项
export interface TemplateItem {
  name: string;
  category: PhotoCategory;
  standard: string;
  photoReq: string;
  riskRule: string;
  regulation: string;
}

// 巡检模板
export interface Template {
  id: string;
  name: string;
  type: "daily" | "standard" | "special";
  typeName: string;
  color: string;
  itemCount: number;
  description: string;
  items: TemplateItem[];
}

// 风险等级
export type RiskLevel = "high" | "mid" | "low";

// 风险状态
export type RiskStatus =
  | "ai_detected" // AI识别
  | "pending" // 待确认
  | "confirmed" // 已确认（待整改）
  | "fixing" // 整改中
  | "fixed" // 已整改
  | "verified"; // 已验证

// 风险项
export interface Risk {
  id: string;
  inspectionId: string;
  description: string;
  level: RiskLevel;
  basis: string; // 判定依据（法规/标准）
  confidence: number; // AI置信度
  suggestion: string; // 整改建议
  status: RiskStatus;
  photoId: string;
  category: PhotoCategory;
  // 整改后照片
  fixedPhotoUrl?: string;
  fixNote?: string;
  fixedTime?: string;
}

// 巡检评级
export type Grade = "优" | "良" | "中" | "差";

// 巡检
export interface Inspection {
  id: string;
  storeId: string;
  templateId: string;
  templateName: string;
  inspector: string;
  inspectTime: string;
  score: number;
  grade: Grade;
  status: "completed" | "analyzing" | "draft";
  riskCount: number;
  highRiskCount: number;
  midRiskCount: number;
  lowRiskCount: number;
  photoCount: number;
}

// 趋势数据点
export interface TrendPoint {
  date: string;
  count: number;
}

// 风险类型分布
export interface RiskTypeData {
  name: string;
  value: number;
}

