import { useState } from "react";
import {
  User, Lock, Bell, Info, Check, Shield, Mail, Phone, Briefcase,
  Save, Eye, EyeOff,
} from "lucide-react";
import { Card, PageHeader, Button } from "@/components/ui";
import { cn } from "@/lib/utils";

type TabKey = "profile" | "password" | "notification" | "about";

const TABS: { key: TabKey; label: string; icon: typeof User }[] = [
  { key: "profile", label: "个人资料", icon: User },
  { key: "password", label: "修改密码", icon: Lock },
  { key: "notification", label: "通知设置", icon: Bell },
  { key: "about", label: "关于系统", icon: Info },
];

export default function Settings() {
  const [activeTab, setActiveTab] = useState<TabKey>("profile");

  return (
    <div className="animate-fadeIn">
      <PageHeader title="系统设置" subtitle="账号与系统偏好配置" />

      <div className="grid grid-cols-[200px_1fr] gap-4">
        {/* 左侧 Tab 菜单 */}
        <Card className="p-2 h-fit sticky top-0">
          <nav className="space-y-1">
            {TABS.map((tab) => {
              const Icon = tab.icon;
              const active = activeTab === tab.key;
              return (
                <button
                  key={tab.key}
                  onClick={() => setActiveTab(tab.key)}
                  className={cn(
                    "w-full flex items-center gap-2 px-3 py-2.5 rounded-md text-sm transition-colors cursor-pointer",
                    active
                      ? "bg-brand-900 text-white"
                      : "text-slate-600 hover:bg-slate-100",
                  )}
                >
                  <Icon className="w-4 h-4" />
                  {tab.label}
                </button>
              );
            })}
          </nav>
        </Card>

        {/* 右侧内容 */}
        <div>
          {activeTab === "profile" && <ProfileTab />}
          {activeTab === "password" && <PasswordTab />}
          {activeTab === "notification" && <NotificationTab />}
          {activeTab === "about" && <AboutTab />}
        </div>
      </div>
    </div>
  );
}

