// ============ 修改密码 ============
function PasswordTab() {
  const [showOld, setShowOld] = useState(false);
  const [showNew, setShowNew] = useState(false);
  const [showConfirm, setShowConfirm] = useState(false);

  return (
    <Card className="p-6">
      <div className="flex items-center gap-2 mb-5 pb-3 border-b border-slate-100">
        <Lock className="w-4 h-4 text-brand-600" />
        <h3 className="text-sm font-semibold text-slate-700">修改密码</h3>
        <span className="text-xs text-slate-400">建议每 90 天更新一次密码</span>
      </div>

      <div className="max-w-md space-y-4">
        <PasswordField
          label="原密码"
          show={showOld}
          onToggle={() => setShowOld(!showOld)}
        />
        <PasswordField
          label="新密码"
          show={showNew}
          onToggle={() => setShowNew(!showNew)}
        />
        <PasswordField
          label="确认新密码"
          show={showConfirm}
          onToggle={() => setShowConfirm(!showConfirm)}
        />

        {/* 密码强度提示 */}
        <div className="bg-slate-50 rounded-md p-3">
          <p className="text-xs text-slate-500 mb-1.5">密码需满足以下要求：</p>
          <ul className="space-y-1 text-xs text-slate-400">
            <li className="flex items-center gap-1.5">
              <Check className="w-3 h-3 text-green-500" />
              长度 8-20 位
            </li>
            <li className="flex items-center gap-1.5">
              <Check className="w-3 h-3 text-green-500" />
              至少包含数字和字母
            </li>
            <li className="flex items-center gap-1.5">
              <Check className="w-3 h-3 text-green-500" />
              区分大小写
            </li>
          </ul>
        </div>

        <div className="flex justify-end gap-2 pt-2">
          <Button variant="ghost" size="md">重置</Button>
          <Button variant="primary" size="md">
            <Check className="w-4 h-4" />
            确认修改
          </Button>
        </div>
      </div>
    </Card>
  );
}

// 密码字段
function PasswordField({
  label, show, onToggle,
}: { label: string; show: boolean; onToggle: () => void }) {
  return (
    <div>
      <label className="flex items-center gap-1 text-xs text-slate-400 mb-1.5">
        <Lock className="w-3 h-3" />
        {label}
      </label>
      <div className="relative">
        <input
          type={show ? "text" : "password"}
          placeholder={`请输入${label}`}
          className="w-full px-3 py-2 pr-10 text-sm border border-slate-200 rounded-md focus:outline-none focus:ring-2 focus:ring-brand-200 focus:border-brand-400 transition"
        />
        <button
          type="button"
          onClick={onToggle}
          className="absolute right-2 top-1/2 -translate-y-1/2 text-slate-400 hover:text-slate-600 cursor-pointer"
        >
          {show ? <EyeOff className="w-4 h-4" /> : <Eye className="w-4 h-4" />}
        </button>
      </div>
    </div>
  );
}

// ============ 通知设置 ============
function NotificationTab() {
  const [toggles, setToggles] = useState({
    inspection: true,
    fix: true,
    report: false,
    system: true,
  });

  const items: { key: keyof typeof toggles; title: string; desc: string }[] = [
    { key: "inspection", title: "巡检提醒", desc: "新巡检任务分配与待办巡检提醒" },
    { key: "fix", title: "整改通知", desc: "风险项整改到期、超期与完成通知" },
    { key: "report", title: "报告生成通知", desc: "周报、月报与专项报告生成完成通知" },
    { key: "system", title: "系统公告", desc: "系统升级、维护与重要公告信息" },
  ];

  const toggle = (k: keyof typeof toggles) =>
    setToggles((t) => ({ ...t, [k]: !t[k] }));

  return (
    <Card className="p-6">
      <div className="flex items-center gap-2 mb-5 pb-3 border-b border-slate-100">
        <Bell className="w-4 h-4 text-brand-600" />
        <h3 className="text-sm font-semibold text-slate-700">通知设置</h3>
        <span className="text-xs text-slate-400">选择你希望接收的通知类型</span>
      </div>

      <div className="space-y-2">
        {items.map((item) => {
          const on = toggles[item.key];
          return (
            <div
              key={item.key}
              className="flex items-center justify-between p-4 rounded-md border border-slate-100 hover:bg-slate-50/50 transition"
            >
              <div className="flex items-start gap-3">
                <div className={cn(
                  "w-9 h-9 rounded-lg flex items-center justify-center",
                  on ? "bg-brand-100" : "bg-slate-100",
                )}>
                  <Bell className={cn("w-4 h-4", on ? "text-brand-700" : "text-slate-400")} />
                </div>
                <div>
                  <p className="text-sm font-medium text-slate-700">{item.title}</p>
                  <p className="text-xs text-slate-400 mt-0.5">{item.desc}</p>
                </div>
              </div>

              {/* Switch */}
              <button
                type="button"
                onClick={() => toggle(item.key)}
                className={cn(
                  "relative w-11 h-6 rounded-full transition-colors cursor-pointer flex-shrink-0",
                  on ? "bg-brand-900" : "bg-slate-300",
                )}
              >
                <span
                  className={cn(
                    "absolute top-0.5 left-0.5 w-5 h-5 rounded-full bg-white shadow-sm transition-transform",
                    on && "translate-x-5",
                  )}
                />
              </button>
            </div>
          );
        })}
      </div>

      <div className="flex justify-end mt-5 pt-4 border-t border-slate-100">
        <Button variant="primary" size="md">
          <Save className="w-4 h-4" />
          保存设置
        </Button>
      </div>
    </Card>
  );
}

