import { useState, useMemo } from "react";
import { useNavigate } from "react-router-dom";
import {
  Plus, MapPin, Phone, User, ChevronLeft, ChevronRight,
  Store as StoreIcon, Search,
} from "lucide-react";
import { Card, PageHeader, Button, SearchInput } from "@/components/ui";
import { stores } from "@/mock";
import { cn } from "@/lib/utils";

const REGIONS = ["全部", "上海", "杭州", "苏州", "南京", "深圳"];
const PAGE_SIZE = 10;

// 平均分颜色配置
function scoreColor(score: number) {
  if (score >= 90) return "text-green-600";
  if (score >= 75) return "text-brand-600";
  if (score >= 60) return "text-orange-500";
  return "text-red-600";
}

function scoreBg(score: number) {
  if (score >= 90) return "bg-green-50";
  if (score >= 75) return "bg-brand-50";
  if (score >= 60) return "bg-orange-50";
  return "bg-red-50";
}

export default function StoreList() {
  const navigate = useNavigate();
  const [keyword, setKeyword] = useState("");
  const [region, setRegion] = useState("全部");
  const [page, setPage] = useState(1);

  // 过滤
  const filtered = useMemo(() => {
    const kw = keyword.trim().toLowerCase();
    return stores.filter((s) => {
      const matchKw = !kw ||
        s.name.toLowerCase().includes(kw) ||
        s.code.toLowerCase().includes(kw);
      const matchRegion = region === "全部" || s.region === region;
      return matchKw && matchRegion;
    });
  }, [keyword, region]);

  // 分页
  const totalPages = Math.max(1, Math.ceil(filtered.length / PAGE_SIZE));
  const safePage = Math.min(page, totalPages);
  const pageData = filtered.slice((safePage - 1) * PAGE_SIZE, safePage * PAGE_SIZE);

  const handleSearch = (v: string) => {
    setKeyword(v);
    setPage(1);
  };

  const handleRegion = (r: string) => {
    setRegion(r);
    setPage(1);
  };

  const goDetail = (id: string) => navigate(`/store/${id}`);

  return (
    <div className="animate-fadeIn">
      <PageHeader
        title="门店管理"
        subtitle="茶小鲜 · 50家门店"
        actions={
          <Button
            variant="primary"
            size="md"
            onClick={() => alert("新增门店功能开发中，敬请期待")}
          >
            <Plus className="w-4 h-4" />
            新增门店
          </Button>
        }
      />

      {/* 筛选区 */}
      <Card className="p-4 mb-4">
        <div className="flex items-center gap-4 flex-wrap">
          <div className="flex-1 min-w-[240px] max-w-md">
            <SearchInput
              value={keyword}
              onChange={handleSearch}
              placeholder="搜索门店名称或编号..."
            />
          </div>
          <div className="flex items-center gap-2">
            <span className="text-xs text-slate-400">区域：</span>
            <div className="flex items-center gap-1">
              {REGIONS.map((r) => (
                <button
                  key={r}
                  onClick={() => handleRegion(r)}
                  className={cn(
                    "px-3 py-1.5 text-xs rounded-md transition-colors cursor-pointer",
                    region === r
                      ? "bg-brand-900 text-white"
                      : "bg-slate-100 text-slate-600 hover:bg-slate-200"
                  )}
                >
                  {r}
                </button>
              ))}
            </div>
          </div>
          <div className="ml-auto text-xs text-slate-400">
            共 <span className="text-brand-700 font-semibold">{filtered.length}</span> 家门店
          </div>
        </div>
      </Card>

      {/* 门店表格 */}
      <Card className="overflow-hidden">
        <table className="w-full text-sm">
          <thead>
            <tr className="bg-slate-50 border-b border-slate-100">
              <th className="px-4 py-3 text-left text-xs font-medium text-slate-500">门店名称</th>
              <th className="px-4 py-3 text-left text-xs font-medium text-slate-500">门店编号</th>
              <th className="px-4 py-3 text-left text-xs font-medium text-slate-500">区域</th>
              <th className="px-4 py-3 text-left text-xs font-medium text-slate-500">地址</th>
              <th className="px-4 py-3 text-left text-xs font-medium text-slate-500">店长</th>
              <th className="px-4 py-3 text-left text-xs font-medium text-slate-500">电话</th>
              <th className="px-4 py-3 text-center text-xs font-medium text-slate-500">平均分</th>
              <th className="px-4 py-3 text-center text-xs font-medium text-slate-500">操作</th>
            </tr>
          </thead>
          <tbody>
            {pageData.length === 0 ? (
              <tr>
                <td colSpan={8} className="px-4 py-16 text-center">
                  <div className="flex flex-col items-center text-slate-300">
                    <Search className="w-10 h-10 mb-2" />
                    <p className="text-sm">未找到符合条件的门店</p>
                  </div>
                </td>
              </tr>
            ) : (
              pageData.map((s) => (
                <tr
                  key={s.id}
                  className="border-b border-slate-50 hover:bg-brand-50/30 transition cursor-pointer"
                  onClick={() => goDetail(s.id)}
                >
                  <td className="px-4 py-3">
                    <div className="flex items-center gap-2">
                      <div className="w-7 h-7 rounded-md bg-brand-100 flex items-center justify-center flex-shrink-0">
                        <StoreIcon className="w-3.5 h-3.5 text-brand-700" />
                      </div>
                      <span className="text-slate-800 font-medium">{s.name}</span>
                    </div>
                  </td>
                  <td className="px-4 py-3">
                    <span className="font-mono text-xs text-slate-600">{s.code}</span>
                  </td>
                  <td className="px-4 py-3">
                    <span className="inline-flex items-center gap-1 text-xs text-slate-600">
                      <MapPin className="w-3 h-3 text-slate-400" />
                      {s.region}
                    </span>
                  </td>
                  <td className="px-4 py-3 text-xs text-slate-500 max-w-[220px] truncate">
                    {s.address}
                  </td>
                  <td className="px-4 py-3">
                    <span className="inline-flex items-center gap-1 text-xs text-slate-600">
                      <User className="w-3 h-3 text-slate-400" />
                      {s.manager}
                    </span>
                  </td>
                  <td className="px-4 py-3">
                    <span className="inline-flex items-center gap-1 text-xs text-slate-600 font-mono">
                      <Phone className="w-3 h-3 text-slate-400" />
                      {s.phone}
                    </span>
                  </td>
                  <td className="px-4 py-3 text-center">
                    <span className={cn(
                      "inline-flex items-center justify-center min-w-[44px] px-2 py-0.5 rounded text-xs font-bold",
                      scoreBg(s.avgScore),
                      scoreColor(s.avgScore),
                    )}>
                      {s.avgScore}
                    </span>
                  </td>
                  <td className="px-4 py-3 text-center">
                    <Button
                      variant="ghost"
                      size="sm"
                      onClick={(e) => {
                        e.stopPropagation();
                        goDetail(s.id);
                      }}
                    >
                      查看详情
                    </Button>
                  </td>
                </tr>
              ))
            )}
          </tbody>
        </table>

        {/* 分页 */}
        <div className="flex items-center justify-between px-4 py-3 border-t border-slate-100">
          <div className="text-xs text-slate-400">
            第 {(safePage - 1) * PAGE_SIZE + 1} -
            {Math.min(safePage * PAGE_SIZE, filtered.length)} 条，
            共 {filtered.length} 条
          </div>
          <div className="flex items-center gap-1">
            <button
              disabled={safePage <= 1}
              onClick={() => setPage((p) => Math.max(1, p - 1))}
              className="w-7 h-7 rounded flex items-center justify-center text-slate-500 hover:bg-slate-100 disabled:opacity-40 disabled:cursor-not-allowed cursor-pointer"
            >
              <ChevronLeft className="w-4 h-4" />
            </button>
            {Array.from({ length: totalPages }).slice(0, 7).map((_, i) => {
              const p = i + 1;
              return (
                <button
                  key={p}
                  onClick={() => setPage(p)}
                  className={cn(
                    "min-w-[28px] h-7 px-2 rounded text-xs cursor-pointer",
                    p === safePage
                      ? "bg-brand-900 text-white"
                      : "text-slate-600 hover:bg-slate-100"
                  )}
                >
                  {p}
                </button>
              );
            })}
            {totalPages > 7 && <span className="text-slate-400 text-xs px-1">...</span>}
            <button
              disabled={safePage >= totalPages}
              onClick={() => setPage((p) => Math.min(totalPages, p + 1))}
              className="w-7 h-7 rounded flex items-center justify-center text-slate-500 hover:bg-slate-100 disabled:opacity-40 disabled:cursor-not-allowed cursor-pointer"
            >
              <ChevronRight className="w-4 h-4" />
            </button>
          </div>
        </div>
      </Card>
    </div>
  );
}
