import { useState, useRef } from "react";
import { useParams, useNavigate } from "react-router-dom";
import {
  ArrowLeft, Download, MapPin, User, Clock, FileText,
  Camera, ScanText, Target, AlertTriangle, CheckCircle2,
} from "lucide-react";
import { Card, PageHeader, Button, ScoreRing, GradeBadge, RiskLevelBadge, RiskStatusBadge } from "@/components/ui";
import {
  getInspection, getStoreName, getPhotosByInspection, getRisksByInspection, getPhoto,
} from "@/mock";
import { cn } from "@/lib/utils";
import { downloadInspectionReport } from "@/lib/report";
import type { Risk } from "@/types";

function getDemoDraft() {
  try {
    return JSON.parse(sessionStorage.getItem("demoInspectionDraft") || "null") as
      | { storeId?: string; templateId?: string }
      | null;
  } catch {
    return null;
  }
}

export default function InspectionDetail() {
  const { id } = useParams();
  const navigate = useNavigate();
  const insp = getInspection(id || "");
  const demoDraft = insp.id === "INS-20260708-001" ? getDemoDraft() : null;
  const displayStoreId = demoDraft?.storeId || insp.storeId;
  const displayTemplateName = demoDraft?.templateId === "tpl-001"
    ? "日常快检"
    : demoDraft?.templateId === "tpl-003"
      ? "专项检查"
      : insp.templateName;
  const photos = getPhotosByInspection(insp.id);
  const risks = getRisksByInspection(insp.id);
  const [activeRisk, setActiveRisk] = useState<Risk | null>(risks[0] || null);
  const [activePhotoId, setActivePhotoId] = useState<string>(risks[0]?.photoId || photos[0]?.id || "");
  const photoRefs = useRef<Record<string, HTMLDivElement | null>>({});

  const activePhoto = getPhoto(activePhotoId);

  const handleRiskClick = (risk: Risk) => {
    setActiveRisk(risk);
    setActivePhotoId(risk.photoId);
    const ref = photoRefs.current[risk.photoId];
    if (ref) ref.scrollIntoView({ behavior: "smooth", block: "center" });
  };

  const handlePDF = () => {
    downloadInspectionReport(
      { ...insp, storeId: displayStoreId, templateName: displayTemplateName },
      getStoreName(displayStoreId),
      risks,
    );
  };

  return (
    <div className="animate-fadeIn">
      <PageHeader
        title="巡检详情"
        subtitle={insp.id}
        actions={
          <div className="flex gap-2">
            <Button variant="secondary" onClick={() => navigate("/inspection")}>
              <ArrowLeft className="w-4 h-4" /> 返回
            </Button>
            <Button onClick={handlePDF}>
              <Download className="w-4 h-4" /> 下载 PDF 报告
            </Button>
          </div>
        }
      />

      {/* 基本信息 + 得分 */}
      <div className="grid grid-cols-3 gap-4 mb-4">
        <Card className="col-span-2 p-5">
          <div className="grid grid-cols-2 gap-4">
            <InfoItem icon={<MapPin className="w-4 h-4" />} label="门店" value={getStoreName(displayStoreId)} />
            <InfoItem icon={<FileText className="w-4 h-4" />} label="模板" value={displayTemplateName} />
            <InfoItem icon={<User className="w-4 h-4" />} label="巡检员" value={insp.inspector} />
            <InfoItem icon={<Clock className="w-4 h-4" />} label="巡检时间" value={insp.inspectTime} />
          </div>
        </Card>
        <Card className="p-5 flex items-center gap-4">
          <ScoreRing score={insp.score} size={90} />
          <div>
            <p className="text-xs text-slate-400">巡检评级</p>
            <div className="mt-1"><GradeBadge grade={insp.grade} /></div>
            <div className="mt-3 flex gap-3 text-xs">
              <span className="text-red-500">高 {insp.highRiskCount}</span>
              <span className="text-orange-500">中 {insp.midRiskCount}</span>
              <span className="text-yellow-500">低 {insp.lowRiskCount}</span>
            </div>
          </div>
        </Card>
      </div>

      {/* 风险溯源 + 照片 */}
      <div className="grid grid-cols-3 gap-4 mb-4">
        {/* 风险清单 */}
        <Card className="p-5">
          <h3 className="text-sm font-semibold text-slate-700 mb-3 flex items-center gap-2">
            <AlertTriangle className="w-4 h-4 text-orange-500" />
            不符合项清单
            <span className="text-xs text-slate-400 font-normal">（{risks.length} 项）</span>
          </h3>
          <div className="space-y-2 max-h-[400px] overflow-y-auto">
            {risks.map((risk) => (
              <div
                key={risk.id}
                onClick={() => handleRiskClick(risk)}
                className={cn(
                  "p-3 rounded-lg border cursor-pointer transition",
                  activeRisk?.id === risk.id
                    ? "border-brand-400 bg-brand-50"
                    : "border-slate-100 hover:bg-slate-50"
                )}
              >
                <div className="flex items-center justify-between mb-1">
                  <RiskLevelBadge level={risk.level} />
                  <RiskStatusBadge status={risk.status} />
                </div>
                <p className="text-sm text-slate-700 line-clamp-2">{risk.description}</p>
                <div className="flex items-center gap-1 mt-1.5 text-xs text-slate-400">
                  <Target className="w-3 h-3" />
                  <span>置信度 {(risk.confidence * 100).toFixed(0)}%</span>
                </div>
              </div>
            ))}
            {risks.length === 0 && (
              <div className="flex flex-col items-center py-8 text-slate-300">
                <CheckCircle2 className="w-8 h-8 mb-2 text-green-300" />
                <p className="text-sm">本次巡检无风险项</p>
              </div>
            )}
          </div>
        </Card>

        {/* 照片 + AI 识别 */}
        <Card className="col-span-2 p-5">
          <h3 className="text-sm font-semibold text-slate-700 mb-3 flex items-center gap-2">
            <Camera className="w-4 h-4 text-brand-500" /> 巡检取证照片
            <span className="text-xs text-slate-400 font-normal">（{photos.length} 张）</span>
          </h3>
          {activePhoto && (
            <div className="mb-4">
              <div
                ref={(el) => { photoRefs.current[activePhoto.id] = el; }}
                className="relative rounded-lg overflow-hidden bg-slate-100"
                style={{ height: 280 }}
              >
                <img
                  src={activePhoto.url}
                  alt={activePhoto.category}
                  className="w-full h-full object-cover"
                />
                {/* 红框标注 */}
                {activePhoto.box && (
                  <div
                    className="absolute border-2 border-red-500 rounded"
                    style={{
                      left: `${activePhoto.box.x}%`,
                      top: `${activePhoto.box.y}%`,
                      width: `${activePhoto.box.w}%`,
                      height: `${activePhoto.box.h}%`,
                      boxShadow: "0 0 0 9999px rgba(0,0,0,0.15)",
                    }}
                  >
                    <span className="absolute -top-6 left-0 bg-red-500 text-white text-xs px-1.5 py-0.5 rounded">
                      {activePhoto.category}
                    </span>
                  </div>
                )}
                {/* 分类标签 */}
                <div className="absolute top-3 right-3 bg-black/60 text-white text-xs px-2 py-1 rounded">
                  {activePhoto.category}
                </div>
              </div>
              {/* AI 识别详情 */}
              <div className="mt-3 bg-slate-50 rounded-lg p-4">
                <div className="flex items-center gap-2 mb-2">
                  <ScanText className="w-4 h-4 text-brand-500" />
                  <span className="text-sm font-medium text-slate-700">AI 识别结果</span>
                  <span className={cn(
                    "ml-auto text-xs px-2 py-0.5 rounded-full",
                    activePhoto.confidence >= 0.9 ? "bg-green-100 text-green-600" : "bg-amber-100 text-amber-600"
                  )}>
                    置信度 {(activePhoto.confidence * 100).toFixed(0)}%
                  </span>
                </div>
                <p className="text-sm text-slate-600">{activePhoto.aiResult}</p>
                {activeRisk && (
                  <div className="mt-3 pt-3 border-t border-slate-200">
                    <div className="flex items-center gap-2 mb-1">
                      <AlertTriangle className="w-3.5 h-3.5 text-red-500" />
                      <span className="text-xs font-medium text-red-600">关联风险</span>
                    </div>
                    <p className="text-sm text-slate-700">{activeRisk.description}</p>
                    <p className="text-xs text-slate-400 mt-1">
                      <span className="font-medium">判定依据：</span>{activeRisk.basis}
                    </p>
                    <p className="text-xs text-slate-400 mt-1">
                      <span className="font-medium">整改建议：</span>{activeRisk.suggestion}
                    </p>
                  </div>
                )}
              </div>
            </div>
          )}

          {/* 缩略图 */}
          <div className="flex gap-2 flex-wrap">
            {photos.map((ph) => (
              <button
                key={ph.id}
                onClick={() => {
                  setActivePhotoId(ph.id);
                  const risk = risks.find((r) => r.photoId === ph.id);
                  if (risk) setActiveRisk(risk);
                }}
                className={cn(
                  "relative w-20 h-20 rounded-lg overflow-hidden border-2 transition",
                  activePhotoId === ph.id ? "border-brand-500" : "border-transparent opacity-60 hover:opacity-100"
                )}
              >
                <img src={ph.url} alt={ph.category} className="w-full h-full object-cover" />
                {risks.find((r) => r.photoId === ph.id) && (
                  <span className="absolute top-1 right-1 w-2 h-2 bg-red-500 rounded-full" />
                )}
              </button>
            ))}
          </div>
        </Card>
      </div>

      {/* 整改状态汇总 */}
      <Card className="p-5">
        <h3 className="text-sm font-semibold text-slate-700 mb-3">整改状态汇总</h3>
        <div className="grid grid-cols-6 gap-3">
          {[
            { label: "AI识别", count: risks.filter((r) => r.status === "ai_detected").length, color: "bg-slate-100 text-slate-600" },
            { label: "待确认", count: risks.filter((r) => r.status === "pending").length, color: "bg-amber-100 text-amber-600" },
            { label: "待整改", count: risks.filter((r) => r.status === "confirmed").length, color: "bg-orange-100 text-orange-600" },
            { label: "整改中", count: risks.filter((r) => r.status === "fixing").length, color: "bg-blue-100 text-blue-600" },
            { label: "已整改", count: risks.filter((r) => r.status === "fixed").length, color: "bg-cyan-100 text-cyan-600" },
            { label: "已验证", count: risks.filter((r) => r.status === "verified").length, color: "bg-green-100 text-green-600" },
          ].map((item) => (
            <div key={item.label} className={cn("rounded-lg p-3 text-center", item.color)}>
              <p className="text-2xl font-bold">{item.count}</p>
              <p className="text-xs mt-1">{item.label}</p>
            </div>
          ))}
        </div>
      </Card>
    </div>
  );
}

function InfoItem({ icon, label, value }: { icon: React.ReactNode; label: string; value: string }) {
  return (
    <div className="flex items-start gap-2">
      <span className="text-slate-400 mt-0.5">{icon}</span>
      <div>
        <p className="text-xs text-slate-400">{label}</p>
        <p className="text-sm text-slate-700 mt-0.5">{value}</p>
      </div>
    </div>
  );
}
