// 日期助手：N天前
function daysAgo(n: number): string {
  const d = new Date();
  d.setDate(d.getDate() - n);
  return d.toISOString().slice(0, 19).replace("T", " ");
}

function calcGrade(score: number): Grade {
  if (score >= 90) return "优";
  if (score >= 75) return "良";
  if (score >= 60) return "中";
  return "差";
}

