// ========== 巡检列表 ==========
function makeInspection(
  id: string, storeId: string, templateId: string, templateName: string,
  inspector: string, daysAgoNum: number, score: number, photoCount: number,
): Inspection {
  const inspRisks = risks.filter((r) => r.inspectionId === id);
  const high = inspRisks.filter((r) => r.level === "high").length;
  const mid = inspRisks.filter((r) => r.level === "mid").length;
  const low = inspRisks.filter((r) => r.level === "low").length;
  return {
    id,
    storeId,
    templateId,
    templateName,
    inspector,
    inspectTime: daysAgo(daysAgoNum),
    score,
    grade: calcGrade(score),
    status: "completed",
    riskCount: inspRisks.length,
    highRiskCount: high,
    midRiskCount: mid,
    lowRiskCount: low,
    photoCount,
  };
}

