export function getInspection(id: string) {
  return inspections.find((i) => i.id === id) || inspections[0];
}

export function getPhotosByInspection(inspectionId: string) {
  return photos.filter((p) => p.inspectionId === inspectionId);
}

export function getPhoto(id: string) {
  return photos.find((p) => p.id === id);
}

export function getRisksByInspection(inspectionId: string) {
  return risks.filter((r) => r.inspectionId === inspectionId);
}

export function getAllRisks() {
  return risks;
}

export function getInspectionsByStore(storeId: string) {
  return inspections.filter((i) => i.storeId === storeId);
}
