import type { TrendPoint, RiskTypeData } from "@/types";
import { stores } from "./stores";
import { inspections } from "./inspections";
import { getAllRisks } from "./inspections";

// 近30天风险趋势
export const riskTrend: TrendPoint[] = (() => {
  const points: TrendPoint[] = [];
  for (let i = 29; i >= 0; i--) {
    const d = new Date();
    d.setDate(d.getDate() - i);
    const dateStr = `${d.getMonth() + 1}/${d.getDate()}`;
    const base = 3 + Math.sin(i * 0.5) * 2;
    const noise = ((i * 7) % 5) * 0.6;
    const count = Math.max(0, Math.round(base + noise));
    points.push({ date: dateStr, count });
  }
  return points;
})();

