// 门店排行（按平均分）
export function getStoreRankings() {
  const sorted = [...stores].sort((a, b) => b.avgScore - a.avgScore);
  return {
    top5: sorted.slice(0, 5),
    bottom5: sorted.slice(-5).reverse(),
  };
}

// Dashboard 统计数据
export function getDashboardStats() {
  const allRisks = getAllRisks();
  const pendingCount = allRisks.filter((r) => r.status === "pending" || r.status === "ai_detected").length;
  const verifiedCount = allRisks.filter((r) => r.status === "verified").length;
  const fixRate = allRisks.length > 0 ? Math.round((verifiedCount / allRisks.length) * 100) : 0;

  // 高风险门店：有高风险项的门店
  const highRiskStoreIds = new Set(
    allRisks.filter((r) => r.level === "high").map((r) => {
      const insp = inspections.find((i) => i.id === r.inspectionId);
      return insp?.storeId;
    }).filter(Boolean)
  );

  // 本月巡检次数
  const now = new Date();
  const thisMonth = inspections.filter((i) => {
    const d = new Date(i.inspectTime);
    return d.getMonth() === now.getMonth() && d.getFullYear() === now.getFullYear();
  }).length;

  return {
    monthlyInspections: thisMonth || inspections.length,
    pendingRisks: pendingCount,
    fixRate,
    highRiskStores: highRiskStoreIds.size,
    totalRisks: allRisks.length,
  };
}
