import { useState, useEffect } from "react";
import {
  Filter, Target, BookOpen, Lightbulb, CheckCircle2,
  ArrowRight, Clock, ScanText,
} from "lucide-react";
import { Card, PageHeader, RiskLevelBadge, RiskStatusBadge, Button } from "@/components/ui";
import BeforeAfterSlider from "@/components/BeforeAfterSlider";
import { getPhoto, getInspection, getStoreName } from "@/mock";
import { useStore } from "@/store/useStore";
import { cn } from "@/lib/utils";
import type { RiskStatus } from "@/types";

const STATUS_FLOW: { status: RiskStatus; label: string }[] = [
  { status: "ai_detected", label: "AI识别" },
  { status: "pending", label: "待确认" },
  { status: "confirmed", label: "待整改" },
  { status: "fixing", label: "整改中" },
  { status: "fixed", label: "已整改" },
  { status: "verified", label: "已验证" },
];

export default function RiskCenter() {
  const { risks, updateRiskStatus, initRisks } = useStore();
  const [levelFilter, setLevelFilter] = useState<string>("all");
  const [statusFilter, setStatusFilter] = useState<string>("all");
  const [activeRiskId, setActiveRiskId] = useState<string>("");

  useEffect(() => {
    initRisks();
  }, [initRisks]);

  const filtered = risks.filter((r) => {
    const matchLevel = levelFilter === "all" || r.level === levelFilter;
    const matchStatus = statusFilter === "all" || r.status === statusFilter;
    return matchLevel && matchStatus;
  });

  // 设置默认选中
  useEffect(() => {
    if (filtered.length > 0 && !filtered.find((r) => r.id === activeRiskId)) {
      setActiveRiskId(filtered[0].id);
    }
  }, [filtered, activeRiskId]);

  const activeRisk = risks.find((r) => r.id === activeRiskId) || filtered[0];
  const activePhoto = activeRisk ? getPhoto(activeRisk.photoId) : null;
  const activeInsp = activeRisk ? getInspection(activeRisk.inspectionId) : null;

  // 下一个状态
  const getNextStatus = (status: RiskStatus): RiskStatus | null => {
    const idx = STATUS_FLOW.findIndex((s) => s.status === status);
    if (idx < 0 || idx >= STATUS_FLOW.length - 1) return null;
    return STATUS_FLOW[idx + 1].status;
  };
  const nextStatus = activeRisk ? getNextStatus(activeRisk.status) : null;
  const nextLabel = nextStatus ? STATUS_FLOW.find((s) => s.status === nextStatus)?.label : null;

  return (
    <div className="animate-fadeIn">
      <PageHeader title="风险中心" subtitle="全部不符合项管理与整改闭环" />

      {/* 筛选栏 */}
      <Card className="p-4 mb-4">
        <div className="flex items-center gap-4 flex-wrap">
          <div className="flex items-center gap-2">
            <Filter className="w-4 h-4 text-slate-400" />
            <span className="text-sm text-slate-400">等级：</span>
            {[
              { key: "all", label: "全部" },
              { key: "high", label: "高风险" },
              { key: "mid", label: "中风险" },
              { key: "low", label: "低风险" },
            ].map((item) => (
              <button
                key={item.key}
                onClick={() => setLevelFilter(item.key)}
                className={cn(
                  "px-3 py-1 rounded text-xs transition cursor-pointer",
                  levelFilter === item.key
                    ? "bg-brand-900 text-white"
                    : "bg-slate-100 text-slate-500 hover:bg-slate-200"
                )}
              >
                {item.label}
              </button>
            ))}
          </div>
          <div className="w-px h-5 bg-slate-200" />
          <div className="flex items-center gap-2">
            <span className="text-sm text-slate-400">状态：</span>
            {[
              { key: "all", label: "全部" },
              { key: "pending", label: "待确认" },
              { key: "confirmed", label: "待整改" },
              { key: "fixing", label: "整改中" },
              { key: "fixed", label: "已整改" },
              { key: "verified", label: "已验证" },
            ].map((item) => (
              <button
                key={item.key}
                onClick={() => setStatusFilter(item.key)}
                className={cn(
                  "px-3 py-1 rounded text-xs transition cursor-pointer",
                  statusFilter === item.key
                    ? "bg-brand-900 text-white"
                    : "bg-slate-100 text-slate-500 hover:bg-slate-200"
                )}
              >
                {item.label}
              </button>
            ))}
          </div>
          <span className="ml-auto text-sm text-slate-400">共 {filtered.length} 项</span>
        </div>
      </Card>

      <div className="grid grid-cols-3 gap-4">
        {/* 风险列表 */}
        <Card className="p-3 max-h-[600px] overflow-y-auto">
          <div className="space-y-2">
            {filtered.map((risk) => {
              const insp = getInspection(risk.inspectionId);
              return (
                <div
                  key={risk.id}
                  onClick={() => setActiveRiskId(risk.id)}
                  className={cn(
                    "p-3 rounded-lg border cursor-pointer transition",
                    activeRisk?.id === risk.id
                      ? "border-brand-400 bg-brand-50"
                      : "border-slate-100 hover:bg-slate-50"
                  )}
                >
                  <div className="flex items-center justify-between mb-1.5">
                    <RiskLevelBadge level={risk.level} />
                    <RiskStatusBadge status={risk.status} />
                  </div>
                  <p className="text-sm text-slate-700 line-clamp-2">{risk.description}</p>
                  <div className="flex items-center gap-2 mt-1.5 text-xs text-slate-400">
                    <span>{getStoreName(insp.storeId)}</span>
                    <span>·</span>
                    <span>{risk.category}</span>
                    <span>·</span>
                    <span className="flex items-center gap-0.5">
                      <Target className="w-2.5 h-2.5" />
                      {(risk.confidence * 100).toFixed(0)}%
                    </span>
                  </div>
                </div>
              );
            })}
          </div>
        </Card>

        {/* 风险详情 */}
        <div className="col-span-2 space-y-4">
          {activeRisk && activePhoto && (
            <>
              {/* 照片 + 红框 */}
              <Card className="p-5">
                <div className="flex items-center justify-between mb-3">
                  <h3 className="text-sm font-semibold text-slate-700">风险溯源</h3>
                  <span className="text-xs text-slate-400">
                    {activeInsp && getStoreName(activeInsp.storeId)} · {activeRisk.category}
                  </span>
                </div>
                <div className="relative rounded-lg overflow-hidden bg-slate-100" style={{ height: 300 }}>
                  <img src={activePhoto.url} alt={activePhoto.category} className="w-full h-full object-cover" />
                  {activePhoto.box && (
                    <div
                      className="absolute border-2 border-red-500 rounded"
                      style={{
                        left: `${activePhoto.box.x}%`,
                        top: `${activePhoto.box.y}%`,
                        width: `${activePhoto.box.w}%`,
                        height: `${activePhoto.box.h}%`,
                        boxShadow: "0 0 0 9999px rgba(0,0,0,0.2)",
                      }}
                    >
                      <span className="absolute -top-6 left-0 bg-red-500 text-white text-xs px-1.5 py-0.5 rounded whitespace-nowrap">
                        问题位置
                      </span>
                    </div>
                  )}
                </div>
                {/* AI 识别 */}
                <div className="mt-3 bg-slate-50 rounded-lg p-4">
                  <div className="flex items-center gap-2 mb-2">
                    <ScanText className="w-4 h-4 text-brand-500" />
                    <span className="text-sm font-medium text-slate-700">AI 识别结果</span>
                    <span className={cn(
                      "ml-auto text-xs px-2 py-0.5 rounded-full",
                      activePhoto.confidence >= 0.9 ? "bg-green-100 text-green-600" : "bg-amber-100 text-amber-600"
                    )}>
                      置信度 {(activePhoto.confidence * 100).toFixed(0)}%
                    </span>
                  </div>
                  <p className="text-sm text-slate-600">{activePhoto.aiResult}</p>
                </div>
              </Card>

              {/* 风险详情 */}
              <Card className="p-5">
                <div className="flex items-center gap-3 mb-4">
                  <RiskLevelBadge level={activeRisk.level} />
                  <RiskStatusBadge status={activeRisk.status} />
                  <span className="text-xs text-slate-400">
                    置信度 {(activeRisk.confidence * 100).toFixed(0)}%
                  </span>
                </div>
                <p className="text-base text-slate-800 font-medium mb-4">{activeRisk.description}</p>

                <div className="grid grid-cols-2 gap-4">
                  <div className="bg-slate-50 rounded-lg p-3">
                    <p className="text-xs text-slate-400 flex items-center gap-1 mb-1">
                      <BookOpen className="w-3 h-3" /> 判定依据
                    </p>
                    <p className="text-sm text-slate-600">{activeRisk.basis}</p>
                  </div>
                  <div className="bg-slate-50 rounded-lg p-3">
                    <p className="text-xs text-slate-400 flex items-center gap-1 mb-1">
                      <Lightbulb className="w-3 h-3" /> 整改建议
                    </p>
                    <p className="text-sm text-slate-600">{activeRisk.suggestion}</p>
                  </div>
                </div>

                {/* 状态流转 */}
                <div className="mt-5">
                  <p className="text-xs text-slate-400 mb-2">整改状态流转</p>
                  <div className="flex items-center gap-1">
                    {STATUS_FLOW.map((s, i) => {
                      const currentIdx = STATUS_FLOW.findIndex((x) => x.status === activeRisk.status);
                      const isPassed = i <= currentIdx;
                      return (
                        <div key={s.status} className="flex items-center">
                          <div className={cn(
                            "px-3 py-1.5 rounded text-xs font-medium transition",
                            isPassed ? "bg-brand-100 text-brand-700" : "bg-slate-50 text-slate-300"
                          )}>
                            {s.label}
                          </div>
                          {i < STATUS_FLOW.length - 1 && (
                            <ArrowRight className={cn("w-3 h-3", isPassed ? "text-brand-300" : "text-slate-200")} />
                          )}
                        </div>
                      );
                    })}
                  </div>
                </div>

                {/* 操作按钮 */}
                {nextStatus && nextLabel && (
                  <div className="mt-4 flex items-center gap-2">
                    <Button
                      onClick={() => updateRiskStatus(activeRisk.id, nextStatus)}
                    >
                      <CheckCircle2 className="w-4 h-4" />
                      {nextLabel === "待整改" ? "确认风险" :
                       nextLabel === "整改中" ? "开始整改" :
                       nextLabel === "已整改" ? "标记已整改" :
                       nextLabel === "已验证" ? "验证通过" : nextLabel}
                    </Button>
                  </div>
                )}
              </Card>

              {/* 整改前后对比 */}
              {activeRisk.fixedPhotoUrl && (
                <Card className="p-5">
                  <h3 className="text-sm font-semibold text-slate-700 mb-1 flex items-center gap-2">
                    <CheckCircle2 className="w-4 h-4 text-green-500" />
                    整改验证 · 前后对比
                  </h3>
                  <p className="text-xs text-slate-400 mb-3">拖动滑块对比整改前后的变化</p>
                  <BeforeAfterSlider
                    beforeUrl={activePhoto.url}
                    afterUrl={activeRisk.fixedPhotoUrl}
                    height={320}
                  />
                  {activeRisk.fixNote && (
                    <div className="mt-3 bg-green-50 rounded-lg p-3">
                      <div className="flex items-center gap-2 mb-1">
                        <CheckCircle2 className="w-3.5 h-3.5 text-green-500" />
                        <span className="text-xs font-medium text-green-700">整改说明</span>
                        {activeRisk.fixedTime && (
                          <span className="text-xs text-slate-400 flex items-center gap-1 ml-auto">
                            <Clock className="w-3 h-3" />{activeRisk.fixedTime.slice(0, 10)}
                          </span>
                        )}
                      </div>
                      <p className="text-sm text-slate-600">{activeRisk.fixNote}</p>
                    </div>
                  )}
                </Card>
              )}
            </>
          )}
        </div>
      </div>
    </div>
  );
}
