import { useState, useRef } from "react";
import { MoveHorizontal } from "lucide-react";

export default function BeforeAfterSlider({
  beforeUrl,
  afterUrl,
  height = 300,
}: {
  beforeUrl: string;
  afterUrl: string;
  height?: number;
}) {
  const [position, setPosition] = useState(50);
  const containerRef = useRef<HTMLDivElement>(null);
  const isDragging = useRef(false);

  const handleMove = (clientX: number) => {
    if (!containerRef.current) return;
    const rect = containerRef.current.getBoundingClientRect();
    const x = clientX - rect.left;
    const pct = Math.max(0, Math.min(100, (x / rect.width) * 100));
    setPosition(pct);
  };

  const handleMouseDown = () => { isDragging.current = true; };
  const handleMouseUp = () => { isDragging.current = false; };
  const handleMouseMove = (e: React.MouseEvent) => {
    if (isDragging.current) handleMove(e.clientX);
  };
  const handleTouchMove = (e: React.TouchEvent) => {
    if (isDragging.current && e.touches[0]) handleMove(e.touches[0].clientX);
  };

  return (
    <div
      ref={containerRef}
      className="relative rounded-lg overflow-hidden select-none cursor-ew-resize"
      style={{ height }}
      onMouseMove={handleMouseMove}
      onMouseUp={handleMouseUp}
      onMouseLeave={handleMouseUp}
      onTouchMove={handleTouchMove}
      onTouchEnd={handleMouseUp}
    >
      {/* 整改后（底层） */}
      <img src={afterUrl} alt="整改后" className="absolute inset-0 w-full h-full object-cover" draggable={false} />
      <span className="absolute top-3 right-3 bg-green-500/90 text-white text-xs px-2 py-1 rounded z-10">
        整改后
      </span>

      {/* 整改前（上层，clip 控制） */}
      <div
        className="absolute inset-0 overflow-hidden"
        style={{ width: `${position}%` }}
      >
        <img
          src={beforeUrl}
          alt="整改前"
          className="absolute inset-0 h-full object-cover"
          style={{ width: containerRef.current?.offsetWidth || "100%" }}
          draggable={false}
        />
        <span className="absolute top-3 left-3 bg-red-500/90 text-white text-xs px-2 py-1 rounded">
          整改前
        </span>
      </div>

      {/* 滑块分割线 */}
      <div
        className="absolute top-0 bottom-0 w-0.5 bg-white shadow-lg pointer-events-none"
        style={{ left: `${position}%`, transform: "translateX(-50%)" }}
      >
        <div className="absolute top-1/2 left-1/2 -translate-x-1/2 -translate-y-1/2 w-9 h-9 rounded-full bg-brand-900 border-2 border-white shadow-lg flex items-center justify-center">
          <MoveHorizontal className="w-4 h-4 text-white" />
        </div>
      </div>

      {/* 滑块控制条 */}
      <input
        type="range"
        min={0}
        max={100}
        value={position}
        onChange={(e) => setPosition(Number(e.target.value))}
        onMouseDown={handleMouseDown}
        className="compare-slider absolute inset-0 w-full h-full opacity-0 cursor-ew-resize"
      />
    </div>
  );
}
